/* Bella Vista – enhancement layer. Load with <script src="enhance.js" defer>. */
(() => {
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
  document.documentElement.classList.add('js');
  const make = (tag, attrs = {}, html = '') => Object.assign(document.createElement(tag), attrs, { innerHTML: html });

  /* scroll progress, sticky-nav state, back-to-top, active nav link */
  const bar = make('div', { id: 'bv-progress' });
  const top = make('button', { id: 'bv-top', ariaLabel: 'Back to top' }, '&#8593;');
  document.body.append(bar, top);
  top.onclick = () => scrollTo({ top: 0 });
  const nav = $('nav');
  const links = $$('nav a[href^="#"]').filter(a => a.getAttribute('href').length > 1);
  const targets = links.map(a => $(a.getAttribute('href'))).filter(Boolean);
  let tick = false;
  const onScroll = () => {
    if (tick) return; tick = true;
    requestAnimationFrame(() => {
      const y = scrollY, max = document.documentElement.scrollHeight - innerHeight;
      bar.style.transform = `scaleX(${max > 0 ? y / max : 0})`;
      nav && nav.classList.toggle('bv-scrolled', y > 40);
      top.classList.toggle('show', y > 700);
      let cur = null;
      targets.forEach(t => { if (t.getBoundingClientRect().top < innerHeight * 0.4) cur = t.id; });
      links.forEach(a => a.classList.toggle('bv-on', a.getAttribute('href') === '#' + cur));
      tick = false;
    });
  };
  addEventListener('scroll', onScroll, { passive: true }); onScroll();

  /* smooth anchor scrolling, offset for the sticky nav */
  document.addEventListener('click', e => {
    const a = e.target.closest('a[href^="#"]');
    if (!a || a.getAttribute('href').length < 2) return;
    const t = $(a.getAttribute('href'));
    if (!t) return;
    e.preventDefault();
    const off = (nav ? nav.offsetHeight : 0) + 8;
    scrollTo({ top: t.getBoundingClientRect().top + scrollY - off });
    history.replaceState(null, '', a.getAttribute('href'));
  });

  /* scroll reveal with gentle stagger */
  const io = 'IntersectionObserver' in window ? new IntersectionObserver(es => es.forEach(e => {
    if (e.isIntersecting) { e.target.classList.add('bv-in'); io.unobserve(e.target); }
  }), { threshold: 0.12, rootMargin: '0px 0px -6% 0px' }) : null;
  const reveal = (sel, step = 0.07) => $$(sel).forEach((el, i) => {
    if (el.classList.contains('bv-rv')) return;
    el.classList.add('bv-rv'); el.style.setProperty('--d', (i % 6) * step + 's');
    io ? io.observe(el) : el.classList.add('bv-in');
  });
  reveal('.concept .facts > *'); reveal('.gal img', 0.09); reveal('.mcards > *');
  reveal('.panel'); reveal('.plan'); reveal('.band > *');

  /* failsafe: never leave content hidden if observers misbehave (e.g. in-app browsers) */
  setTimeout(() => $$('.bv-rv').forEach(el => el.classList.add('bv-in')), 2500);
  addEventListener('pageshow', () => $$('.bv-rv').forEach(el => el.classList.add('bv-in')));

  /* menu panel: fade in on every tab / filter change, re-reveal new dishes */
  const menu = $('#menu');
  if (menu) {
    let busy = false;
    new MutationObserver(() => {
      if (busy) return; busy = true;
      menu.classList.remove('bv-swap'); void menu.offsetWidth; menu.classList.add('bv-swap');
      setTimeout(() => { busy = false; }, 60);
    }).observe(menu, { childList: true });
  }

  /* gallery lightbox: tap to open, swipe or arrows to browse, Esc / tap outside to close */
  const imgs = $$('#gal img');
  if (imgs.length) {
    const lb = make('div', { id: 'bv-lb', role: 'dialog', ariaLabel: 'Photo viewer' },
      '<button id="bv-x" aria-label="Close">&times;</button><button id="bv-p" aria-label="Previous">&#8249;</button>' +
      '<img alt=""><button id="bv-n" aria-label="Next">&#8250;</button><div id="bv-c"></div>');
    document.body.append(lb);
    const pic = $('img', lb), count = $('#bv-c', lb);
    let i = 0;
    const show = n => {
      i = (n + imgs.length) % imgs.length;
      pic.src = imgs[i].currentSrc || imgs[i].src; pic.alt = imgs[i].alt || '';
      count.textContent = `${i + 1} / ${imgs.length}`;
    };
    const open = n => { show(n); lb.classList.add('open'); document.body.style.overflow = 'hidden'; };
    const close = () => { lb.classList.remove('open'); document.body.style.overflow = ''; };
    imgs.forEach((im, n) => im.addEventListener('click', () => open(n)));
    $('#bv-x', lb).onclick = close;
    $('#bv-p', lb).onclick = () => show(i - 1);
    $('#bv-n', lb).onclick = () => show(i + 1);
    lb.addEventListener('click', e => { if (e.target === lb) close(); });
    addEventListener('keydown', e => {
      if (!lb.classList.contains('open')) return;
      if (e.key === 'Escape') close();
      if (e.key === 'ArrowLeft') show(i - 1);
      if (e.key === 'ArrowRight') show(i + 1);
    });
    let sx = 0;
    lb.addEventListener('touchstart', e => { sx = e.touches[0].clientX; }, { passive: true });
    lb.addEventListener('touchend', e => {
      const dx = e.changedTouches[0].clientX - sx;
      if (Math.abs(dx) > 50) show(i + (dx < 0 ? 1 : -1));
    }, { passive: true });
  }

  /* hero: soft parallax on the glow (skipped for reduced motion) */
  const hero = $('.hero');
  if (hero && !matchMedia('(prefers-reduced-motion: reduce)').matches) {
    addEventListener('scroll', () => {
      if (scrollY < innerHeight) hero.style.backgroundPositionY = scrollY * 0.25 + 'px';
    }, { passive: true });
  }
})();

/* ---------- Phone helpers: menu drawer, bottom bar, booking layout, auto table pick ---------- */
(()=>{
 const $=i=>document.getElementById(i),mq=matchMedia('(max-width:860px)');
 const burger=$('burger'),mnav=$('mnav'),mbar=$('mbar');
 const setNav=o=>{if(!burger)return;burger.setAttribute('aria-expanded',o);burger.setAttribute('aria-label',o?'Close menu':'Open menu');mnav.hidden=!o;document.body.classList.toggle('navopen',o);mbar&&mbar.classList.toggle('hide',o)};
 if(burger){burger.onclick=()=>setNav(burger.getAttribute('aria-expanded')!=='true');
  mnav.addEventListener('click',e=>{if(e.target.closest('a'))setNav(false)});
  addEventListener('keydown',e=>{if(e.key==='Escape')setNav(false)});}
 /* hide the bottom bar while typing, so it never sits on top of the keyboard */
 if(mbar){document.addEventListener('focusin',e=>{if(e.target.matches('input,select,textarea'))mbar.classList.add('hide')});
  document.addEventListener('focusout',()=>setTimeout(()=>{if(!document.activeElement||!document.activeElement.matches('input,select,textarea'))mbar.classList.remove('hide')},150));}
 /* bottom bar "Menus" opens the menu cards */
 if(mbar&&mbar.querySelector('a[href="#menus"]'))mbar.querySelector('a[href="#menus"]').addEventListener('click',()=>{if(typeof closeMenus==='function'&&$('mcards').hidden)closeMenus()});
 /* gallery hint on phones */
 const gal=$('gal');if(gal&&!$('galhint')){const h=document.createElement('p');h.id='galhint';h.className='gal-hint';h.textContent='Swipe to see more →';h.hidden=!mq.matches;gal.after(h)}
 /* booking: on phones put the arrival times between "when" and "your details" */
 const pw=$('planwrap'),home=pw&&pw.parentElement,st3=$('st3');
 const place=()=>{if(!pw||!st3)return;
  if(mq.matches){if(pw.parentElement!==st3.parentElement)st3.before(pw)}
  else if(pw.parentElement!==home)home.prepend(pw);
  const gh=$('galhint');if(gh)gh.hidden=!mq.matches};
 place();mq.addEventListener?mq.addEventListener('change',place):mq.addListener(place);
})();

